  app/views/cards/display/_public_previews.html.erb
  app/views/cards/previews/index.turbo_stream.erb
  app/views/public/boards/card_previews/index.turbo_stream.erb
]
paths.each do |path|
  text = File.read(path)
  text.sub!('cached: true', 'cached: ->(card) { [ card, card.stalled? ] }')
  File.write(path, text)
end

path = 'app/helpers/cards_helper.rb'
text = File.read(path)
text.sub!('      ("card--postponed" if card.postponed?),\n', '      ("card--postponed" if card.postponed?),\n      ("card--stalled" if card.stalled?),\n')
File.write(path, text)

path = 'app/views/cards/_card.json.jbuilder'
text = File.read(path)
text.sub!('json.cache! card do', 'json.cache! [ card, card.stalled? ] do')
text.sub!('  json.golden card.golden?\n', '  json.golden card.golden?\n  json.stalled card.stalled?\n')
File.write(path, text)

path = 'app/views/notifications/_notification.json.jbuilder'
