text.sub!('json.cache! notification do', 'json.cache! [ notification, notification.card.stalled? ] do')
text.sub!('    json.closed notification.card.closed?\n', '    json.closed notification.card.closed?\n    json.stalled notification.card.stalled?\n')
File.write(path, text)
