    padding: 1.1lh 1lh 1lh;
    position: relative;
    text-align: start;
    z-index: 2;

    .events section:first-of-type & {
      border-radius: 0.5em 0.5em 0 0;
    }

    &:has(.events__activity--generating) {
      --border-color: var(--color-selected-dark);

      animation: gradient 4s ease infinite;
      background: linear-gradient(-45deg, var(--color-gradient-1), var(--color-gradient-2), var(--color-gradient-3), var(--color-gradient-4));
      background-size: 300%;
      text-align: center;
    }

    > * {
      column-count: 2;
      column-gap: var(--inline-space-double);
      margin-inline: auto;
      max-inline-size: 80ch;
    }

    a {
      color: inherit;
    }

    h3 {
      column-span: all;
      font-size: var(--text-large);
      line-height: 1.3;
      margin-block: 0.5em 0.25em;
      text-align: center;
      text-wrap: balance;

      + p {
        column-span: all;
        font-size: var(--text-medium);
        margin-block: 0 1.5em;
        text-align: center;
        text-wrap: balance;
      }
    }

    h4 {
      break-after: avoid-column;
      font-size: var(--text-medium);
      line-height: 1.3;
      margin-block: 0.5em 0.25em;
      text-wrap: balance;

      + p {
        break-inside: avoid-column;
        margin-block: 0 1.5em;
      }
    }

    hr { display: none; }
  }

  .events__activity-generating-msg {
    display: block;
    font-weight: 500;
    margin-block: 2lh;
    opacity: 0.5;
  }

  .events__activity-prompt-edit {
    inset: auto 1em 1em auto;
    position: absolute;
  }

